bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'JS'
import {readdirSync,readFileSync} from 'node:fs';
import {join} from 'node:path';
const root='/opt/videobot/src', hits=[];
function scan(dir){
 for(const e of readdirSync(dir,{withFileTypes:true})){
  const p=join(dir,e.name);
  if(e.isDirectory())scan(p);
  else if(e.isFile()&&p.endsWith('.mjs')){
   const lines=readFileSync(p,'utf8').split('\n');
   for(let i=0;i<lines.length;i++){
    const line=lines[i].trim();
    if(/(sendVideo|sendMediaGroup|sendPaidMedia|copyMessage|forwardMessage|publishVideoListing|buildPaidMediaRequest)/.test(line)){
     hits.push({module:p.slice(root.length+1),line:i+1,text:line.slice(0,170)});
    }
   }
  }
 }
}
scan(root);
for(const h of hits)console.log(h.module+':'+h.line+' '+h.text);
console.log('SCANNED_PUBLICATION_REFERENCES='+hits.length);
JS
